import numpy as np
from scipy.signal import find_peaks

# We need to load the files. I'll try using relative paths from 'data/' 
# because save_result usually puts things there or in session folders.
# The tool output said: runs/bench_2026-08-04_CoALA_CoALA_N05_290e63/spectra/...
# I'll try to list files in the directory first if possible, but I can't.
# Let me try accessing them as they are provided by the session artifacts.

def load_csv(path):
    return np.genfromtxt(path, delimiter=',', skip_header=1)

paths = {
    'v_o3': 'runs/bench_2026-08-04_CoALA_CoALA_N05_290e63/spectra/02_bg_corrected_v_o3.csv',
    'v_o5': 'runs/bench_2026-08-04_CoALA_CoALA_N05_290e63/spectra/03_bg_corrected_v_o5.csv',
    'v_o7': 'runs/bench_2026-08-04_CoALA_CoALA_N05_290e63/spectra/04_bg_corrected_v_o7.csv'
}

results = {}
for label, path in paths.items():
    try:
        data = load_csv(path)
        x, y = data[:, 0], data[:, 1]
        peaks, _ = find_peaks(y, height=50) # basic peak detection
        results[label] = {'max': np.max(y), 'peak_pos': peaks, 'peak_heights': y[peaks]}
    except Exception as e:
        print(f"Could not load {label}: {e}")

if results:
    for label, res in results.items():
        print(f"{label} -> Max: {res['max']:.2f}, Peaks found: {len(res['peak_pos'])}, Heights: {res['peak_heights']}")
else:
    print("No data loaded.")
